<script setup lang="ts">
import { ArrowRight, CheckCircle2, Eye, EyeOff } from '@lucide/vue'; import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; import BrandLogo from '../components/BrandLogo.vue'
const email=ref('');const password=ref('');const remember=ref(false);const visible=ref(false);const loading=ref(false);const error=ref('');const auth=useAuthStore();const router=useRouter()
async function submit(){loading.value=true;error.value='';try{const data=await auth.login({email:email.value,password:password.value,remember:remember.value});router.replace(data.verification_required?'/verify-email':'/dashboard')}catch(e:any){error.value=e.response?.data?.message||'We could not sign you in.'}finally{loading.value=false}}
</script>
<template><main class="auth-layout"><section class="auth-story"><BrandLogo light/><div class="story-copy"><span class="eyebrow light">YOUR ACADEMY, IN ONE PLACE</span><h1>Start the day<br><em>with everything clear.</em></h1><p>A focused workspace for Egyptian teachers and training centres.</p><ul><li><CheckCircle2/>See today’s sessions at a glance</li><li><CheckCircle2/>Keep every student record connected</li><li><CheckCircle2/>Work comfortably in Arabic or English</li></ul></div><footer>CAIRO · EGYPT <span>SECURE BY DESIGN</span></footer></section><section class="auth-panel"><div class="auth-box"><span class="eyebrow">WELCOME BACK</span><h2>Your workspace awaits.</h2><p>Sign in to continue managing your academy.</p><form @submit.prevent="submit"><label>Email address<input v-model="email" type="email" autocomplete="email" placeholder="you@academy.com" required></label><label>Password<div class="password-field"><input v-model="password" :type="visible?'text':'password'" autocomplete="current-password" placeholder="Enter your password" required><button type="button" @click="visible=!visible"><EyeOff v-if="visible"/><Eye v-else/></button></div></label><div class="form-row"><label class="check"><input v-model="remember" type="checkbox"> Remember me</label><RouterLink to="/forgot-password">Forgot password?</RouterLink></div><div v-if="error" class="form-error">{{ error }}</div><button class="button primary wide" :disabled="loading">{{loading?'Signing in…':'Sign in to AcademyHub'}} <ArrowRight/></button></form><div class="separator"><span>NEW TO ACADEMYHUB?</span></div><RouterLink to="/register" class="button secondary wide">Create your academy workspace</RouterLink><small class="fine-print">By continuing, you agree to our Terms and Privacy Policy.</small></div></section></main></template>
